import json
import os
import re

from silence.db.schema import get_schema
from silence.settings import settings
from silence.project.files import write_json, write_text
from silence.project import molds
from silence.server.endpoints import (REGISTRY, AUTO_PREFIX, endpoints_dir,
                                      route_key, table_of_file)

###############################################################################
# Generation (on demand, from the admin panel) of the autogenerated endpoints
# (endpoints/auto_<table>.json) and of the JS API to call them
# (web/js/api/_auto/<table>.js). They are all public (the student asks for
# authentication, roles or an owner when customizing them), also those of the
# users table, which is a table like the others (in argon2 mode, its reads do
# not send the passwords and its writes store them encrypted; in plain mode,
# they are stored and sent as they are).
###############################################################################



def crud_endpoints(rel):
    '''The CRUD endpoints of a table (or only getAll for a view or a table without a single PK).
    All of them public: requiring a session, roles or an owner is what customizing is for'''
    name = rel.name
    route_all = "/" + name.lower()
    res = {
        "getAll": {
            "description": f"Gets all entries from '{name}'",
            "route": route_all, "method": "GET",
            "sql": f"SELECT * FROM {name}",
            "auth_required": False, "allowed_roles": ["*"],
        }
    }
    pk = rel.single_pk
    if rel.is_view or pk is None:
        return res

    route_one = f"{route_all}/${pk}"
    insertable = [c.name for c in rel.columns.values() if not c.auto_increment and not c.generated]
    updatable = [c for c in insertable if c != pk]

    res["getById"] = {
        "description": f"Gets an entry from '{name}' by its primary key",
        "route": route_one, "method": "GET",
        "sql": f"SELECT * FROM {name} WHERE {pk} = ${pk}",
        "auth_required": False, "allowed_roles": ["*"],
    }
    if insertable:
        res["create"] = {
            "description": f"Creates a new entry in '{name}'",
            "route": route_all, "method": "POST",
            "sql": f"INSERT INTO {name}({', '.join(insertable)}) VALUES ({', '.join('$' + c for c in insertable)})",
            "auth_required": False, "allowed_roles": ["*"],
            "request_body_params": insertable,
        }
    if updatable:
        res["update"] = {
            "description": f"Updates an existing entry in '{name}' by its primary key",
            "route": route_one, "method": "PUT",
            "sql": f"UPDATE {name} SET {', '.join(f'{c} = ${c}' for c in updatable)} WHERE {pk} = ${pk}",
            "auth_required": False, "allowed_roles": ["*"],
            "request_body_params": updatable,
        }
    res["delete"] = {
        "description": f"Deletes an existing entry in '{name}' by its primary key",
        "route": route_one, "method": "DELETE",
        "sql": f"DELETE FROM {name} WHERE {pk} = ${pk}",
        "auth_required": False, "allowed_roles": ["*"],
    }
    return res


def custom_keys():
    '''Method and route of every custom endpoint (they are never generated again). Not the
    disabled ones: the autogenerated one stays in its file, to come back when the copy is deleted'''
    REGISTRY.load()
    keys = {e.key for e in REGISTRY.endpoints if e.source == "custom"}
    # Also the ones in files with errors (e.g., duplicated), read directly
    folder = endpoints_dir()
    if os.path.isdir(folder):
        for f in os.listdir(folder):
            if f.endswith(".json") and not f.startswith(AUTO_PREFIX):
                try:
                    with open(os.path.join(folder, f), encoding="utf8") as fh:
                        for data in json.load(fh).values():
                            if not data.get("disabled"):
                                keys.add(route_key(data.get("method", "GET"), data.get("route", "")))
                except (ValueError, AttributeError):
                    pass
    return keys


def check_tables(schema, tables):
    '''ValueError if some name is not a table or view of the database (with a suggestion)'''
    import difflib
    names = list(schema.relations)
    for t in tables or []:
        if schema.get(t) is None:
            close = difflib.get_close_matches(t, names, n=1)
            hint = f" Did you mean '{close[0]}'?" if close else f" The tables and views are: {', '.join(names)}."
            raise ValueError(f"There is no table or view '{t}' in {settings.DB_CONN['database']}.{hint}")


def generate(tables=None):
    '''Writes endpoints/auto_<table>.json for the given tables and views (all
    by default) and their JS API. Returns a summary per table'''
    schema = get_schema(refresh=True)
    check_tables(schema, tables)
    customs = custom_keys()
    folder = endpoints_dir()
    os.makedirs(folder, exist_ok=True)
    selected = list(schema.relations.values()) if tables is None else [schema.get(t) for t in dict.fromkeys(tables)]
    summary = []

    for rel in selected:
        all_eps = crud_endpoints(rel)
        auto = {n: d for n, d in all_eps.items() if route_key(d["method"], d["route"]) not in customs}
        skipped = [n for n in all_eps if n not in auto]
        path = os.path.join(folder, f"{AUTO_PREFIX}{rel.name}.json")
        if auto:
            write_json(path, auto)
        elif os.path.isfile(path):
            os.remove(path)
        disabled = {e.key for e in REGISTRY.disabled}
        write_js_api(rel, {n: d for n, d in all_eps.items() if route_key(d["method"], d["route"]) not in disabled})
        summary.append({"table": rel.name, "view": rel.is_view, "generated": list(auto), "custom": skipped})

    # Autogenerated files (and their JS API) of tables that no longer exist, whatever is generated
    removed = []
    names = {r.name for r in schema.relations.values()}
    for f in os.listdir(folder):
        if f.startswith(AUTO_PREFIX) and f.endswith(".json") and table_of_file(f) not in names:
            os.remove(os.path.join(folder, f))
            removed.append(f)
            js = js_api_dir()
            js_file = os.path.join(js, f"{table_of_file(f).lower()}.js") if js else None
            if js_file and os.path.isfile(js_file):
                os.remove(js_file)

    write_js_common()
    REGISTRY.load()
    js_state = js_api_state()
    return {"tables": summary, "removed": removed,
            "jsApi": {"dir": settings.JS_API_DIR if js_state is None else None, "notGenerated": js_state}}


###############################################################################
# JS API: from the molds of the project (.silence/js_api/, brought by its
# template; see docs/molds.md). Without them, it is not generated
###############################################################################

def js_function(name, ep):
    params = re.findall(r"\$(\w+)", ep["route"])
    has_body = ep["method"] in ("POST", "PUT")
    values = {"name": name, "description": ep.get("description", ""), "method": ep["method"].lower(),
              "METHOD": ep["method"], "route": re.sub(r"\$(\w+)", r"${\1}", ep["route"]),
              "params": ", ".join(params), "args": ", ".join((["formData"] if has_body else []) + params),
              "body": ", formData" if has_body else ""}
    if name == "getById":
        return molds.fill("js_api", "function_one.js", values, fallback="function.js")
    return molds.fill("js_api", "function.js", values)


JS_MOLDS = ("table.js", "function.js", "common.js")


def js_api_state():
    '''Whether the JS API is generated, and why not: None if it is, or the reason'''
    if not settings.JS_API_ENABLED or not settings.JS_API_DIR:
        return "disabled in silence.json (js_api)"
    absent = [m for m in JS_MOLDS if not molds.has("js_api", m)]
    if absent:
        return (f"the project has no molds for it ({', '.join('.silence/js_api/' + m for m in absent)}): "
                "they come with its template")
    return None


def js_api_dir():
    '''Folder of the generated JS API (js_api in silence.json), or None if it is not generated'''
    if js_api_state() is not None:
        return None
    return os.path.join(settings.PROJECT_DIR, *settings.JS_API_DIR.split("/"))


def write_js_api(rel, eps):
    folder = js_api_dir()
    if folder is None:
        return
    var = rel.name.lower()
    functions = "".join(js_function(n, e) for n, e in eps.items())
    write_text(os.path.join(folder, f"{var}.js"), molds.fill("js_api", "table.js", {"table": var, "functions": functions}))


def write_js_common():
    '''common.js of the generated API: what the files share (the base URL, the session header...)'''
    folder = js_api_dir()
    if folder is None:
        return
    write_text(os.path.join(folder, "common.js"), molds.fill("js_api", "common.js", {"api_prefix": settings.API_PREFIX}))
